def build(N, start_index):
	up = [[None] * N for _ in range(20)]
	up[0] = start_index
	for i in range(1, 20):
		for j in range(N):
			p = up[i - 1][j]
			if p == -1:
				up[i][j] = -1
			else:
				up[i][j] = up[i - 1][p]
	return up

def call(up, node, K):
	(last, jump) = (node, 1)
	for i in range(19):
		if node == -1:
			break
		if K & jump:
			node = up[i][node]
		jump <<= 1
	return last - node

def solve(nums, N, K, S):
	(start_index, j, curr) = ([], 0, 0)
	for i in range(N):
		curr += nums[i]
		while curr > S:
			curr -= nums[j]
			j += 1
		start_index.append(j - 1)
	up = build(N, start_index)
	res = 0
	for i in range(N - 1, -1, -1):
		res = max(res, call(up, i, K))
	return res
T = int(input())
for _ in range(T):
	(N, K, S) = tuple(map(int, input().split()))
	nums = list(map(int, input().split()))
	print(solve(nums, N, K, S))
